1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * The single derived key used to detect duplicate owners, consolidating what were once
9	 * separate telephone, email and household checks into one value:
10	 * {@code normalizedTelephone + "|" + (email or empty) + "|" + householdId}.
11	 *
12	 * <p>The telephone is compared in canonical E.164 form (see {@link OwnerTelephone}); the email
13	 * is lower-cased and rendered empty when absent; the householdId is rendered empty when the
14	 * owner shares no household. Creation is rejected with 409 only when a new owner's WHOLE
15	 * identityKey equals an existing owner's — so, because the telephone is part of the key, two
16	 * members of the same household with different telephones have different keys and are both
17	 * allowed. See {@link EnsureUniqueOwnerIdentity}.
18	 */
19	public final class OwnerIdentityKey {
20	
21	    private OwnerIdentityKey() {
22	    }
23	
24	    /** The identityKey of a stored owner, from its telephone, email and householdId. */
25	    public static String of(Owner owner) {
26	        return of(owner.getTelephone(), owner.getEmail(), owner.getHouseholdId());
27	    }
28	
29	    /** The identityKey for the given telephone, email and householdId. */
30	    public static String of(String telephone, String email, String householdId) {
31	        String tel = OwnerTelephone.canonical(telephone);
32	        String mail = (email == null || email.isBlank()) ? "" : email.toLowerCase(Locale.ROOT);
33	        String household = (householdId == null) ? "" : householdId;
34	        return tel + "|" + mail + "|" + household;
35	    }
36	}
