1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.Locale;
7	
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.repository.OwnerRepository;
10	
11	/**
12	 * Shared derivation of an owner's household identity — the normalized last name and address
13	 * (case-insensitive, collapsed whitespace) and the stable {@code householdId} computed from
14	 * them. Used by {@link AssignOwnerHousehold} (which assigns and back-fills the id) and by
15	 * {@link EnsureUniqueOwnerIdentity} (which needs the id a request would resolve to, to build
16	 * its {@link OwnerIdentityKey}), so both agree on exactly what a household is.
17	 */
18	final class OwnerHousehold {
19	
20	    private OwnerHousehold() {
21	    }
22	
23	    /**
24	     * The {@code householdId} the given last name and address would resolve to if at least one
25	     * existing owner already shares that household, otherwise {@code null} (a solo owner keeps a
26	     * null householdId).
27	     */
28	    static String resolve(String lastName, String address, OwnerRepository ownerRepository) {
29	        String ln = normalizeName(lastName);
30	        String ad = normalizeAddress(address);
31	        for (Owner existing : ownerRepository.findAll()) {
32	            if (ln.equals(normalizeName(existing.getLastName()))
33	                    && ad.equals(normalizeAddress(existing.getAddress()))) {
34	                return id(ln, ad);
35	            }
36	        }
37	        return null;
38	    }
39	
40	    /** Stable 12-char upper-hex identifier derived from the normalized household key. */
41	    static String id(String normalizedLastName, String normalizedAddress) {
42	        String key = normalizedLastName + "\n" + normalizedAddress;
43	        try {
44	            byte[] digest = MessageDigest.getInstance("SHA-256")
45	                    .digest(key.getBytes(StandardCharsets.UTF_8));
46	            StringBuilder sb = new StringBuilder(12);
47	            for (int i = 0; i < 6; i++) {
48	                sb.append(String.format("%02X", digest[i]));
49	            }
50	            return sb.toString();
51	        }
52	        catch (NoSuchAlgorithmException e) {
53	            throw new IllegalStateException(e);
54	        }
55	    }
56	
57	    /** Lower-cases and collapses runs of whitespace to a single space, trimming the ends. */
58	    static String normalizeName(String value) {
59	        if (value == null) {
60	            return "";
61	        }
62	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
63	    }
64	
65	    /** Address comparison uses the same normalized form the endpoint stores (see {@link OwnerAddress}). */
66	    static String normalizeAddress(String value) {
67	        String normalized = OwnerAddress.normalize(value);
68	        return normalized == null ? "" : normalized;
69	    }
70	}
