1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.ArrayList;
4	import java.util.List;
5	
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.repository.OwnerRepository;
9	
10	/**
11	 * Assigns a shared {@code householdId} to a newly built owner that shares a household
12	 * with one or more existing owners (same last name and address, compared
13	 * case-insensitively with collapsed whitespace — see {@link OwnerHousehold}).
14	 *
15	 * <p>Runs after {@link BuildOwner} and before {@link SaveOwner}, so genuine housemates are
16	 * grouped under one identifier. The identifier is derived deterministically from the
17	 * normalized last name and address, so every member of a household resolves to the same
18	 * value regardless of creation order; existing members that predate the household are
19	 * back-filled with it. An owner with no housemate keeps a {@code null} householdId. The
20	 * same derivation feeds the duplicate key in {@link EnsureUniqueOwnerIdentity}.
21	 */
22	public class AssignOwnerHousehold {
23	
24	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
25	        String lastName = OwnerHousehold.normalizeName(owner.getLastName());
26	        String address = OwnerHousehold.normalizeAddress(owner.getAddress());
27	        List<Owner> housemates = new ArrayList<>();
28	        for (Owner existing : ownerRepository.findAll()) {
29	            if (lastName.equals(OwnerHousehold.normalizeName(existing.getLastName()))
30	                    && address.equals(OwnerHousehold.normalizeAddress(existing.getAddress()))) {
31	                housemates.add(existing);
32	            }
33	        }
34	        if (housemates.isEmpty()) {
35	            return; // no shared household
36	        }
37	        String householdId = OwnerHousehold.id(lastName, address);
38	        owner.setHouseholdId(householdId);
39	        for (Owner mate : housemates) {
40	            if (mate.getHouseholdId() == null || mate.getHouseholdId().isBlank()) {
41	                mate.setHouseholdId(householdId);
42	                ownerRepository.save(mate);
43	            }
44	        }
45	    }
46	}
