1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	import net.officefloor.plugin.variable.Val;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.rest.function.common.Localities;
10	
11	/**
12	 * Assigns the {@code customerCode} to a newly built owner, formatted
13	 * {@code <REGION>-<HASH8>} where {@code REGION} is the region code derived from the
14	 * owner's postcode (see {@link Localities#locality(String, String)}) and {@code HASH8}
15	 * is the first 8 upper-case hex characters of the SHA-256 digest over the owner's
16	 * normalized telephone (E.164, see {@link OwnerTelephone}) concatenated with its last
17	 * name (e.g. {@code NSW-1A2B3C4D}).
18	 *
19	 * <p>This is a stable identity: it carries no sequence number, so it does not depend on
20	 * how many owners already exist. Every value built from the customerCode — the
21	 * membershipNumber and its checkDigit, the create audit line and the derived locality —
22	 * follows from this region-and-hash identity. Mutates the owner in place (the same object
23	 * {@link SaveOwner} persists).
24	 */
25	public class AssignOwnerCustomerCode {
26	
27	    public void service(@Val Owner owner) {
28	        String region = Localities.locality(owner.getCity(), owner.getPostcode());
29	        String telephone = OwnerTelephone.canonical(owner.getTelephone());
30	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
31	        owner.setCustomerCode(region + "-" + hash8(telephone + lastName));
32	    }
33	
34	    /** The first 8 upper-case hex characters of the SHA-256 digest of {@code input}. */
35	    private static String hash8(String input) {
36	        try {
37	            byte[] digest = MessageDigest.getInstance("SHA-256")
38	                    .digest(input.getBytes(StandardCharsets.UTF_8));
39	            StringBuilder sb = new StringBuilder(8);
40	            for (int i = 0; i < 4; i++) {
41	                sb.append(String.format("%02X", digest[i]));
42	            }
43	            return sb.toString();
44	        }
45	        catch (NoSuchAlgorithmException e) {
46	            throw new IllegalStateException(e);
47	        }
48	    }
49	}
